        text: '三頭は政敵を処罰者名簿に載せて殺害し、財産を没収した。弁論家キケロもこのとき殺された。前42年、三頭の軍はマケドニアのフィリッピでブルートゥス・カッシウスの共和派を破り、2人は自害した。',
