        talk: '敵がいなくなると、今度は3人の間で争いが始まります。まずレピドゥスが力を失い、残ったのは西のオクタウィアヌスと、東のアントニウスでした。アントニウスはエジプトの女王クレオパトラと結ばれ、ローマの領土を彼女の子どもたちに分けると約束します。オクタウィアヌスはこれを「ローマをエジプトに売る気だ」と宣伝しました。前31年、ギリシア西岸のアクティウムの海戦で、オクタウィアヌスの艦隊が勝利しました。',
