    period: '16〜17世紀', region: 'europe', view: 'europe', tags: ['tankyu', 'sogo'],
    summary: '国境で区切られた領土の中で、外からの干渉を受けない最高の権力（主権）をもつ国家。中世の教皇や皇帝といった普遍的な権威が弱まるなかで生まれ、ウェストファリア条約以後、対等な主権国家が並び立つ体制が広まった。今の国際社会の基本の形である。',
