        talk: '中世のヨーロッパで「この土地はだれのもの？」と聞くと、答えはひとつではありませんでした。土地は領主のもの、でも領主は国王の家臣で、教会の土地には教皇の力が及び、町は自分たちの特権をもっていました。一人の人が、いくつもの主人に従っていたのです。国境も、今の地図のようにはっきり線が引かれてはいません。王といっても、国の中のすべてを決められるわけではなかったのです。',
