        talk: '主権国家が生まれるきっかけのひとつが、イタリア戦争でした。フランスとハプスブルク家が、豊かなイタリアをめぐって60年以上も争ったのです。長い戦いに勝つには、いつでも戦える常備軍と、税を集める役人が必要です。王は国の中の力を自分に集めていきました。また、イタリアの都市国家が始めた、相手の国に大使を置きっぱなしにする外交が広がります。国と国が対等に交渉する、今の外交の原型です。',
