        text: 'フランスでは宗教戦争（ユグノー戦争）が続くなか、法学者ジャン=ボーダンが1576年に『国家論』を著し、主権を「国家の絶対的で永続的な権力」と定義した。主権は王に属し、王が法をつくるとした。',
        talk: '「主権」という言葉をはっきり定義したのは、フランスの法学者ボーダンです。当時のフランスは、カトリックとプロテスタントが殺し合うユグノー戦争の真っ最中でした。ボーダンは考えます。国がばらばらになるのは、だれが最後に決めるのかがはっきりしないからだ、と。そこで、国の中で最高の、ほかに分けられない権力として「主権」を定め、それは王がもつとしました。この考えは、のちの絶対王政を支える理論となります。',
