        talk: '30年続いた戦争を終わらせるため、ドイツのミュンスターとオスナブリュックに、ヨーロッパ中の使節が集まりました。会議は5年近くかかりました。ここで、神聖ローマ帝国の300ほどの領邦が、ほぼ独立国のような権利を得ます。皇帝も教皇も、もはや国の上に立つことはできません。大小の国が対等に並ぶ、これが主権国家体制です。ただし近年の研究では、この体制は1648年に一気にできたのではなく、少しずつ形づくられたとも考えられています。',
