        talk: '「封建」という言葉は、もともと中国の周の時代の言葉です。「土地を封じて国を建てる」という意味です。殷を倒した周の王は、広い土地を一人で治めることはできません。そこで弟や息子、手柄を立てた家臣に土地を分け、諸侯として各地を治めさせました。そのかわり、諸侯は王に貢ぎ物をおさめ、戦争のときは兵を出します。王と諸侯をつないだのは、親戚としての「血のつながり」でした。',
