        talk: '血のつながりで結ばれたしくみには、弱点がありました。何代もたつと、王と諸侯はとおい親戚になり、「王に従う理由」が薄れていくのです。周の王の力が弱まると、諸侯はそれぞれ独立した国のようにふるまい、たがいに戦い始めました。この反省から、中国を統一した秦の始皇帝は、土地を一族に分けるのをやめます。かわりに、皇帝が選んだ役人を各地に送る郡県制にしたのです。',
