    title: '租調庸制 ― 土地をもらったら、穀物・布・労働で返す',
    period: '6世紀末〜780年', region: 'east', view: 'china', tags: ['tankyu'],
    summary: '隋・唐の税制で、均田制で土地を受けた成年男性に、租（穀物）・調（布など）・庸（労役か、その代わりの布）を同じ額だけ課した。土地を配ることとセットのしくみだったため、均田制が崩れると成り立たなくなり、780年に両税法に改められた。',
