        year: 701, title: '日本にも伝わった「租庸調」',
        text: '租調庸のしくみは東アジアにも広がった。日本では701年の大宝律令で、班田収授法とともに租・庸・調の税制が定められ、各地から都に調の品物が運ばれた。木簡にはその荷札が残る。',
        talk: '日本の歴史の授業で「租庸調」という言葉を習いましたね。実は、日本の税のしくみは唐をお手本にしたものでした。701年の大宝律令で、口分田を配る班田収授法と、租・庸・調の税が定められます。地方の人々は、調として布や海産物を自分たちで都まで運びました。平城京の跡から見つかる木簡には、「どこの国の、だれが、何を」納めたかを書いた荷札がたくさん残っています。唐の制度は、海をこえて日本の村にも届いていたのです。',
