        text: '敦煌などから見つかった唐代の戸籍によると、実際に割り当てられた土地は規定よりかなり少ない場合が多かった。それでも税は人数ごとに一律にかかったため、重い負担に苦しむ農民も多かった。',
        talk: '規則どおりに土地は配られていたのでしょうか。その答えを教えてくれるのが、敦煌の石窟などで見つかった唐の時代の戸籍です。そこには、家族の名前や年齢とともに、受けとった土地の広さが書かれています。調べてみると、決まりの広さの半分にも満たない家も少なくありませんでした。それなのに、税は一人あたり同じ額がかかります。土地が少ない家ほど苦しい。紙の記録から、村の現実が見えてくるのです。',
