        talk: '人口が増えれば、配る土地はいずれ足りなくなります。さらに、重い税や兵役から逃げ出す農民が増え、逃げた人の分まで残った人にのしかかりました。そこに755年、安禄山の大反乱が起こります。戸籍はめちゃくちゃになり、だれがどこに住んでいるのかも分からなくなりました。そこで780年、唐は発想を変えます。人の数ではなく、今もっている土地や財産に応じて、夏と秋の2回税をとる両税法です。',
