    period: '10〜15世紀', region: 'east', view: 'eastasia', tags: ['tankyu'],
    summary: '仏教の経典をすべて集めた大蔵経は、宋や高麗で木版印刷された。とくに高麗は、契丹やモンゴルの侵入を仏の力で退けようと大蔵経を刊行し、8万枚をこえる版木が今も海印寺に残る。東アジアの印刷技術と信仰の結晶である。',
