        text: '1232年、モンゴル軍の侵入で初彫大蔵経の版木は焼失した。高麗は都を江華島に移して抵抗を続けるとともに、1236年から1251年にかけて再び大蔵経の版木を彫った。これが再彫大蔵経で、8万1000枚あまりにのぼる。',
        talk: '1232年、こんどはモンゴル軍がやってきます。初彫大蔵経の版木は、このとき炎の中に消えてしまいました。高麗の王は、海に囲まれた江華島に都を移して抵抗を続けます。そして、もう一度大蔵経を彫ることを決めました。16年かけて彫られた版木は、8万1000枚あまり。積み上げると、高い山よりも高くなるといわれます。しかも、5000万字をこえる文字に、ほとんど誤りがないことで知られています。',
