        talk: '8万枚の版木は、やがて南の山の中にある海印寺に運ばれました。ここで版木を守ってきたのが、蔵経板殿という建物です。一見ただの木の倉庫ですが、実は、上と下で窓の大きさを変えて風が建物の中をめぐるようにし、床の土が湿気を吸ったり吐いたりするように工夫されています。電気もエアコンもない時代の知恵で、版木は600年以上、虫にも食われず残りました。1995年には世界遺産になっています。',
