        talk: '海印寺の版木から刷られた大蔵経は、海をこえて日本にも渡りました。室町時代の守護大名や将軍は、何度も朝鮮に使者を送り、この大蔵経を求めています。それほど貴重なものだったのです。さらに1924年から日本で出版された『大正新脩大蔵経』も、高麗版をもとにしています。今、世界中の研究者が仏典を調べるとき、その多くがこの本を使います。モンゴルと戦った人々の祈りが、今の学問を支えているのです。',
