        talk: 'なぜコロッセウムは、ローマのど真ん中にあるのでしょうか。実はそこには、もともと暴君ネロの宮殿の池がありました。大火事のあと、ネロは焼けた市街地に、自分だけのぜいたくな宮殿と庭をつくったのです。市民は怒っていました。ネロの死後、皇帝となったウェスパシアヌスは、その池を埋めて、市民みんなが楽しめる闘技場を建てると決めます。皇帝の土地を市民に返す、という人気取りのアピールでもあったのです。',
