        talk: '80年、闘技場が完成すると、皇帝ティトゥスは100日間も続くお祭りを開きました。剣闘士の試合、猛獣狩り、さらには闘技場に水を張って船の戦いを見せたとも伝えられています。歴史家の記録では、このとき9000頭の動物が殺されたといいます。入場は無料でした。詩人ユウェナリスは、市民が求めるのは「パンとサーカス」だけだと皮肉っています。皇帝は食べ物と娯楽を与えて、市民の人気を集めたのです。',
