        text: '1753年、医師ハンス=スローンが集めた7万点をこえる収集品が国に遺贈され、議会は法律を定めて大英博物館を創設した。1759年、ロンドンのモンタギュー=ハウスで、学びたい人のために無料で公開された。',
        talk: '大英博物館の始まりは、一人のお医者さんのコレクションでした。ハンス=スローンは、植物の標本や化石、硬貨、本など、7万点をこえる品を一生かけて集めました。彼は亡くなる前、これを国が買い取って、みんなのために残してほしいと願います。議会はくじの収益でお金を集め、1753年に博物館をつくりました。1759年の開館のとき、入館は無料。王や貴族だけでなく「学びたい人すべて」に開かれた、当時としては画期的な施設でした。',
        place: 'ロンドン（ブルームズベリー）', lon: -0.127, lat: 51.519, span: 0.3,
        polities: ['britain'],
        lines: [{ name: 'テムズ川', pts: [[-0.17, 51.485], [-0.125, 51.5], [-0.105, 51.51], [-0.075, 51.507]] }]
