        year: 1857, title: '円形閲覧室の常連たち',
        text: '19世紀半ば、ギリシア神殿風の現在の建物が完成し、1857年には中庭に円形閲覧室が開かれた。亡命中のマルクスはここで経済学を研究して『資本論』を著し、のちに孫文も利用した。',
        talk: '博物館の中心には、ドーム屋根の大きな円形閲覧室がつくられました。ここは図書館でもあり、許可を得た人は膨大な本を無料で読むことができました。その常連の一人が、ドイツから亡命してきたマルクスです。彼は何年もここに通い、資料を読みこんで『資本論』を書き上げました。のちには、中国の革命家の孫文もこの閲覧室を利用しています。世界を変える思想が、博物館の机から生まれていたのです。',
        place: 'ロンドン（大英博物館）', lon: -0.127, lat: 51.519, span: 0.3,
