        talk: '大英博物館には、世界中の文化財があります。それは、イギリスが世界中に植民地を広げた「帝国」の時代と深く結びついています。ギリシアのパルテノン神殿の彫刻は、オスマン帝国の支配下で、イギリス大使エルギン卿が持ち出したものです。西アフリカのベニン王国の美しい青銅像は、1897年にイギリス軍が都を攻め落としたとき、戦利品として持ち去られました。展示ケースの中の一つひとつに、こうした歴史が隠れています。',
