        talk: '今も大英博物館は入館無料で、毎年数百万人が訪れます。世界の文化をひとつの場所で見比べられる、すばらしい学びの場です。しかし、ギリシアは「パルテノンの彫刻はアテネに返すべきだ」と、ナイジェリアは「ベニンの青銅像を返してほしい」と訴え続けています。ドイツなどではベニン青銅像を返す動きも始まりました。文化財は、つくった人々の子孫のものか、人類みんなのものか。あなたなら、どう考えますか。',
