    summary: '熱帯・亜熱帯で、輸出用の作物を大量に単一栽培する大農園。アメリカ大陸では、アフリカから連れてこられた奴隷が砂糖・タバコ・綿花づくりに使役された。ヨーロッパの豊かさと大西洋奴隷貿易を支え、今も続く単一作物に頼る経済の原因ともなった。',
