        talk: 'プランテーションの原型は、アメリカ大陸ではなく、大西洋の島々で生まれました。15世紀、ポルトガルは無人のマデイラ諸島や、アフリカの赤道直下のサントメ島で、サトウキビを育て始めます。サトウキビは刈りとったらすぐしぼらないと甘さが落ちるため、畑の近くに製糖所を置き、昼も夜も働かせる必要がありました。その重労働を担わされたのが、アフリカ大陸から連れてこられた人々です。この組み合わせが、やがて大西洋をわたります。',
