        text: '1793年にホイットニーが綿繰り機を発明すると、アメリカ南部で綿花のプランテーションが急拡大した。綿花はイギリスの綿工業の原料となり、南部の奴隷人口は1860年に約400万人に達した。',
        talk: '18世紀の終わり、アメリカ南部で新しいプランテーションがブームになります。綿花です。綿の実から種を取り除く綿繰り機が発明されて作業が何十倍も速くなり、さらにイギリスの工場が大量の綿を求めていたからです。綿花畑は西へ広がり、そこで働く奴隷の数もふくれ上がって、1860年には約400万人になりました。イギリスの産業革命の機械を動かした原料は、アメリカの奴隷がつんだ綿だったのです。この問題が、やがて南北戦争につながります。',
