        talk: '19世紀、奴隷制は世界各地で廃止されていきます。イギリスは1833年、アメリカは南北戦争後の1865年、そして最後がブラジルの1888年でした。でも、プランテーションはなくなりませんでした。かわりにインドや中国から、安い賃金で長期間働く契約労働者が集められます。さらにマレー半島のゴムなど、アジアやアフリカにも広がりました。一つの作物の輸出に頼る「モノカルチャー経済」は、今も多くの国の課題になっています。',
