        talk: '1830年、マンチェスターと港町リヴァプールの間に、世界初の本格的な旅客鉄道が開通しました。走ったのは、スティーヴンソン親子の蒸気機関車です。綿花はリヴァプールの港に陸揚げされ、鉄道でマンチェスターの工場へ。できあがった綿布は、また鉄道で港へ運ばれ、世界中に輸出されます。鉄道をつくるには、大量の鉄と石炭が必要です。こうして鉄道がさらに工業を育て、イギリス中に線路が広がっていきました。',
