        talk: '資本主義のしくみを最初に体系的に説明したのが、スコットランドの学者アダム=スミスです。彼はピン工場の例をあげました。1人で全部の作業をすると、1日に20本もつくれない。でも、針金を伸ばす人、切る人、とがらせる人と作業を分けると、10人で1日4万8000本もつくれる、と。さらにスミスは、みんなが自分の利益を考えて自由に商売すれば、まるで「見えざる手」に導かれるように、社会全体が豊かになると考えました。',
