        talk: '産業革命で、たくさんの機械を置いた工場が建てられました。工場や機械を持つ人を資本家、そこで働いて給料をもらう人を労働者といいます。資本家はもうけを大きくしようと、給料を安く、働く時間を長くしようとしました。1日14時間以上働くこともめずらしくなく、10歳にもならない子どもまでが働いていました。工場の町マンチェスターでは、すすけた空気と、ぎゅうぎゅう詰めの家で、多くの人が病気になりました。',
