        text: '労働者の貧しさを見たマルクスは、資本主義では資本家が労働者の生み出した価値を利潤として得ていると批判し、1867年に『資本論』第1巻を刊行した。社会主義の思想は労働運動とともに広がった。',
        talk: '「豊かな人はますます豊かに、貧しい人はますます貧しくなるのは、なぜか」。この問いにとり組んだのがマルクスでした。ロンドンの大英博物館の図書室にこもって研究し、1867年に『資本論』を出版します。マルクスは、労働者が生み出した価値の一部を、資本家がもうけとして手に入れているのだと考えました。そして、いずれ労働者が立ち上がり、資本主義は終わると予言します。この考えは、20世紀に世界を二つに分けるほどの力をもつことになります。',
