        talk: '広すぎる帝国を一人で守るのは無理だ、とディオクレティアヌスは考えました。そこで293年、帝国を4つに分け、正帝2人と副帝2人で治める四帝分治を始めます。自分は東の正帝として、今のトルコのニコメディアにいました。さらに、物価の上昇を止めようと、1000をこえる品物やサービスの値段の上限を定めた最高価格令も出します。でも、決められた値段では商売にならず、品物が市場から消えてしまったといわれています。',
