        talk: '皇帝を神のように崇めさせる体制にとって、困った人々がいました。キリスト教徒です。彼らは唯一の神だけを拝み、皇帝の像に香をたくことをこばみました。303年、ディオクレティアヌスは、教会をこわし、聖書を焼き、信者を役職から追い出すよう命じます。多くの人が殉教しました。でも、迫害してもキリスト教はなくなりませんでした。それどころか、わずか10年後の313年、コンスタンティヌス帝がキリスト教を公認することになります。',
