        talk: '整理の中心になったのが、法学者トリボニアヌスです。いちばんの大仕事は、昔の法学者たちの学説をまとめる作業でした。ユスティニアヌスによると、2000冊、300万行もの文章を読み、必要な部分だけ選んで、50巻、15万行にまとめたといいます。それをわずか3年でやりとげたのです。さらに、法律を学ぶ学生のための教科書もつくりました。ギリシア語を話す人が多い東ローマで、あえて伝統のラテン語でまとめられた点も特徴です。',
