    period: '13〜14世紀', region: 'inner', view: 'eurasia', tags: ['tankyu'],
    summary: 'モンゴル帝国が整えた駅伝制度。主要な道路に一定の間隔で駅（站）を置き、通行証（牌子）を持つ使者に馬や食料を提供した。広大な帝国を一つにつなぐ情報の道であり、商人や旅行者の往来も支えて、東西の交流を大きく進めた。',
