        talk: 'チンギス=カンが一代で築いたモンゴル帝国は、モンゴル高原から中央アジア、さらに西へと広がっていました。1229年に後を継いだオゴタイは、さらに金を滅ぼし、ヨーロッパまで軍を送ります。でも、こんなに広い国で、命令が届くのに何か月もかかっていては治められません。「遠くの出来事を、すぐに知り、すぐに命令を届けたい」。そのためにオゴタイが整えたのが、ジャムチと呼ばれる駅伝制度でした。',
