        talk: 'しくみはこうです。都のカラコルムから四方へのびる道に、数十キロごとに駅を置きます。駅には元気な馬と食料が用意されていて、近くの住民がその世話を受けもちました。使者は、皇帝からもらった牌子という通行証を見せれば、疲れた馬を乗りすてて、新しい馬に乗りかえることができます。牌子は金や銀、木でつくられ、身分によって種類がちがいました。今でいえば、どこでも使える最強のパスポートのようなものです。',
