        talk: 'フビライの宮廷に仕えたヴェネツィア出身のマルコ=ポーロは、この駅伝制度にとても驚きました。『世界の記述』の中で、駅には立派な宿があり、数百頭もの馬が用意されていると書いています。急ぎの知らせを運ぶ使者は、鈴をつけた帯を締めて走り、鈴の音を聞いた次の駅の者が、すぐに乗りかえの馬を用意したといいます。元の時代、中国の中だけで1400か所あまりの駅があったとされます。帝国は情報のスピードでつながっていたのです。',
