        talk: '神聖ローマ帝国の皇帝は、親から子へ自動的に受け継がれるのではなく、有力な諸侯が選ぶことになっていました。でも、だれに選ぶ権利があるのか、何票で決まるのかがあいまいでした。そのため、二人の皇帝が同時に選ばれるような混乱も起こります。13世紀半ばには、しばらく実質的に皇帝がいない「大空位時代」まで生まれました。1273年、ようやくハプスブルク家のルドルフ1世が選ばれますが、問題は解決していませんでした。',
