        talk: '1356年、皇帝カール4世がこの問題に決着をつけます。プラハを都とするボヘミア王でもあったカール4世は、ニュルンベルクとメッツで帝国の会議を開き、選挙のルールを文書にまとめました。この文書には、皇帝の金の印章がぶら下げられていました。だから「金印勅書」と呼ばれるのです。ふつうの文書にはろうや鉛の印を使いましたが、とくに大切な文書には金を使いました。それだけ重要な決まりだったということです。',
