        text: '金印勅書は、マインツ・ケルン・トリーアの3大司教と、ボヘミア王・ライン宮中伯・ザクセン公・ブランデンブルク辺境伯の7人を選帝侯とし、多数決で皇帝を選ぶと定めた。選帝侯には領内の裁判権や鉱山・貨幣の権利などの特権が認められた。',
