        talk: '皇帝の選挙は、フランクフルトの大聖堂で行うと決められました。この勅書には、教皇の承認が必要だとは書かれていません。皇帝を選ぶのはドイツの諸侯だ、という宣言でもありました。その後、1438年からは、ほとんどの時代でハプスブルク家の当主が選ばれ続けます。選挙といっても、実際には一つの家が皇帝の位を受け継ぐようになったのです。それでも、選帝侯の機嫌をとるために、皇帝は特権を与え続けなければなりませんでした。',
