    summary: '1534年、イギリス国王ヘンリ8世が制定した法律。国王をイギリス国内の教会の唯一の首長とし、ローマ教皇から離れてイギリス国教会が成立した。きっかけは王の離婚問題だったが、修道院の解散などを通じて、国王の権力とイギリス社会を大きく変えた。',
