        talk: 'もともとヘンリ8世は、熱心なカトリックでした。ルターを批判する本を書き、教皇から「信仰の擁護者」という称号までもらっています。そのヘンリが、なぜ教皇とけんかすることになったのでしょう。理由は跡継ぎでした。王妃キャサリンとの間には、王女メアリしか育ちませんでした。ばら戦争の記憶が残るイギリスでは、王に男の子がいなければ、また内乱が起きるかもしれません。ヘンリは、若いアン=ブーリンと結婚したいと考えるようになったのです。',
