        text: 'カトリックでは離婚が認められず、教皇クレメンス7世は結婚の無効を認めなかった。キャサリンの甥である皇帝カール5世の軍が1527年にローマを略奪しており、教皇はカール5世に逆らえなかった。1533年、ヘンリは教皇の許可なくアンと結婚した。',
        talk: 'カトリックでは、離婚は認められていません。そこでヘンリは、そもそもこの結婚は最初から無効だった、と認めてもらおうとしました。ところが教皇は首をたてにふりません。実は、王妃キャサリンの甥は、ヨーロッパ最強の皇帝カール5世でした。その軍隊は1527年にローマを荒らしたばかりで、教皇はカール5世をおそれていたのです。待ちきれないヘンリは、1533年、ひそかにアンと結婚してしまいます。',
