        talk: '1534年、ヘンリは議会を通じて首長法を成立させます。「国王は、イングランドの教会の、地上における唯一最高の首長である」。つまり、イギリスの教会のトップは、教皇ではなく国王だということです。これで、ヘンリの結婚にローマの許可はいらなくなりました。教会の裁判や、教会が教皇に送っていたお金も、すべて国王のものになります。王個人の結婚問題から、国の宗教のかたちそのものが変わってしまったのです。',
