        talk: '1571年、スペインはフィリピンにマニラの町をつくります。そしてメキシコの港アカプルコとマニラの間に、ガレオン船と呼ばれる大きな帆船を走らせました。太平洋の横断は、片道で数か月もかかる命がけの航海です。とくに帰り道は北の海流と風を使う長い航路で、半年近くかかることもありました。それでも船は、およそ250年にわたって太平洋を往復し続けます。積み荷のいちばんは、もちろん銀でした。',
