        talk: 'マニラの港には、中国の福建から帆船に乗った商人たちが、毎年のようにやってきました。積んでいるのは、生糸や絹織物、陶磁器です。スペイン人は、これをメキシコから運んできた銀で買い取りました。中国の絹は、メキシコやペルー、そしてスペインで高く売れたのです。こうして、アメリカの銀は太平洋を渡り、アジアの品物はアメリカを通ってヨーロッパへ。地球を一周する交易の輪ができあがりました。',
        place: 'マニラ', lon: 120.98, lat: 14.6, span: 20,
        polities: ['spanish-philippines', 'ming'],
        marks: [{ name: '月港（福建）', lon: 117.85, lat: 24.45 }],
        routes: [{ name: '中国のジャンク船', color: '#c0392b', pts: [[117.85, 24.45], [119.0, 20.0], [120.98, 14.6]] }]
