        text: '大量の銀が流入すると、明では税や労役を銀でまとめて納める一条鞭法が16世紀後半に広まり、張居正の時代に全国に実施された。清では18世紀に、丁税を土地税に組みこむ地丁銀制が行われた。',
        talk: '海の向こうから大量の銀が入ってくると、中国の暮らしも変わりました。それまで農民は、米や布、そして労働で税を納めていました。ところが明の後半になると、さまざまな税や労役をまとめて計算し、銀で納めるしくみが広がります。これが一条鞭法です。宰相の張居正の時代、1581年ごろに全国に広まりました。農民は作物を市場で売り、銀にかえて税を納めます。メキシコの鉱山と、中国の村の税が、ひとつにつながったのです。',
