        talk: '最後に、意外なつながりをお話しします。メキシコの銀貨、メキシコドルは、品質が安定していたので、19世紀の東アジアの貿易では「世界のお金」として使われていました。幕末の日本の港でも、この銀貨が大量に使われています。そこで明治政府は、1871年に新しいお金の単位「円」を定めたとき、貿易用の1円銀貨を、メキシコドルとほぼ同じ重さと品質にしました。私たちが毎日使う「円」のルーツは、メキシコの銀にあったのです。',
