        talk: 'ヴェルサイユ宮殿の始まりには、王の嫉妬があったといわれます。1661年、財務長官フーケが、自分の豪華な城に若いルイ14世を招いて盛大な宴を開きました。王よりもぜいたくな家来がいてよいはずがありません。まもなくフーケは捕らえられ、ルイ14世はその城をつくった建築家、庭師、画家をそっくり呼び寄せます。そして父の狩りのための小さな館があったヴェルサイユに、だれも見たことのない宮殿を建て始めたのです。',
