        talk: '1682年、ルイ14世は宮廷と政府ごと、ヴェルサイユに引っ越しました。宮殿の中心にあるのが「鏡の間」です。長さ約73メートル、片側の壁には357枚の鏡がはめこまれ、向かいの窓から入る光を映して、きらきらと輝きます。当時、大きな鏡はとても高価で、ヴェネツィアの職人しかつくれないとされていました。それをフランスの工場でつくらせたこと自体が、王の力と国の技術の自慢だったのです。',
