        talk: '宮殿での一日は、王が目を覚ます儀式から始まります。王のシャツを手わたす役目は、もっとも位の高い貴族だけに許された名誉でした。貴族たちは、王に名前を覚えてもらおうと、豪華な服を着て、毎日宮殿に通いつめます。これがルイ14世のねらいでした。貴族を宮廷の儀式とぜいたくな暮らしにしばりつけておけば、地方の領地で反乱を起こすひまも、お金もなくなります。華やかな宮殿は、貴族を飼いならすしかけでもあったのです。',
