        talk: '四方を敵に囲まれたマリア=テレジアが向かったのは、ハンガリーでした。1741年、プレスブルクのハンガリー議会で、彼女は貴族たちに助けを求めます。ハプスブルク家に反発することも多かったハンガリー貴族たちでしたが、若い女王の必死の訴えに心を動かされ、「われらの命と血を！」と叫んだと伝えられています。生まれたばかりの王子を抱いて訴えたという有名な話もありますが、これは後から脚色された部分もあるようです。',
        place: 'プレスブルク（ブラチスラヴァ）', lon: 17.11, lat: 48.15, span: 3,
