        talk: 'この戦争は、ヨーロッパの中だけでは終わりませんでした。イギリスはオーストリアの味方、フランスはプロイセンの味方につき、英仏は世界中の植民地でもぶつかります。北アメリカでは、イギリス植民地の人々がフランスの要塞を攻めました。インドでは1746年、フランスがイギリスの重要な拠点マドラスを占領します。ヨーロッパの王位をめぐる争いが、地球の反対側の人々まで巻きこむ。世界戦争の時代が始まりつつあったのです。',
