        talk: '戦争の火種は、北アメリカの森の中にありました。大西洋岸に人口の多いイギリスの13植民地。内陸にはカナダからミシシッピ川にそって広がるフランスの領土。両者がぶつかったのが、オハイオ川の流域でした。1754年、この地に送られたイギリス植民地の若い将校が、フランス軍と戦って降伏します。その将校の名は、ジョージ=ワシントン。のちのアメリカ初代大統領です。フランスは多くの先住民と手を結んだため、フレンチ=インディアン戦争と呼ばれます。',
