        talk: '1759年9月、カナダのケベックの町は、高い崖の上にある天然の要塞でした。イギリスのウルフ将軍は、夜の闇にまぎれて兵を小舟で運び、細い道から崖をよじ登らせます。夜明け、町の前の平原にイギリス軍が並んでいるのを見て、フランス軍は驚きました。戦いはわずか十数分ほどで決着したといわれます。しかし、この戦いでウルフも、フランスのモンカルム将軍も命を落としました。ケベックの陥落で、カナダの運命は決まりました。',
