        talk: '1763年2月、パリで講和条約が結ばれました。地図を見ると、その結果は一目瞭然です。フランスはカナダとミシシッピ川の東をイギリスにゆずり、川の西のルイジアナはスペインにわたしました。北アメリカの大陸から、フランスの領土はほとんど消えたのです。ただし、フランスは砂糖の島グアドループなどは取りもどしました。フランスの思想家ヴォルテールが、カナダを「数エーカーの雪」と言ったように、砂糖の島のほうが大事だと考える人もいたのです。',
