        text: '編纂の過程では、満洲人を「夷狄」とするなど清朝に不都合な内容の書物が禁書とされ、約3000種が焼かれたり、文章が書きかえられたりした。四庫全書には、文化事業と思想統制という二つの顔があった。',
        talk: '四庫全書には、もう一つの顔がありました。集められた本の中には、北方の民族を「夷狄」、つまり野蛮人とばかにしたり、明をなつかしんだりする本もありました。満洲人の清にとって、これは許せません。そうした本は禁書とされ、約3000種が焼かれたといわれます。残された本でも、都合の悪い言葉はこっそり書きかえられました。文化を守る大事業は、同時に、皇帝にとって危険な考えを消し去る作業でもあったのです。',
