        text: '四庫全書は合わせて7部つくられ、紫禁城の文淵閣、円明園の文源閣、熱河の避暑山荘の文津閣、瀋陽の文溯閣の北方4か所と、揚州・鎮江・杭州の江南3か所に収められた。江南の3部は学者の閲覧が許された。',
        talk: '四庫全書は、全部で7部つくられました。北京の紫禁城と円明園、夏の離宮があった熱河、清のふるさと瀋陽の4か所。そして、学問がさかんな江南の揚州・鎮江・杭州の3か所です。宮殿の4部は皇帝のためのものでしたが、江南の3部は、学者たちが書庫に入って読み、写すことも許されていました。手書きの本7部を、遠く離れた7つの町に分けて置いたのは、火事や戦争で全部が失われるのを防ぐためでもあったようです。',
        place: '杭州（文瀾閣）', lon: 120.15, lat: 30.25, span: 14,
