        talk: '7部の四庫全書は、その後の戦争にほんろうされます。1860年、アロー戦争で北京に入ったイギリス・フランス軍が円明園を焼き、そこにあった1部が灰になりました。太平天国の乱では、揚州と鎮江の本が焼け、杭州の本も半分以上が失われます。杭州の本は、のちに人々が写し直して補いました。そして紫禁城の文淵閣の本は、1949年、国共内戦に敗れた国民党によって台湾に運ばれ、今は台北の故宮博物院にあります。',
