        talk: '1814年、ナポレオンがエルバ島に流されると、ヨーロッパ中の君主や外交官がウィーンに集まりました。20年以上続いた革命と戦争で、国境も王朝もめちゃくちゃになっていたからです。議長は、オーストリアのメッテルニヒ。ところが、会議の合間には毎晩のように舞踏会が開かれ、各国は自分の取り分をめぐって譲りません。「会議は踊る、されど進まず」。参加者の一人がこう皮肉ったといわれています。',
        place: 'ウィーン', lon: 16.37, lat: 48.21, span: 1,
        polities: ['austria', 'russia', 'prussia', 'britain', 'france'], people: ['metternich', 'napoleon']
