      {
        year: 1814, title: 'タレーランの切り札',
        text: '敗戦国フランスの代表タレーランは、革命前の正統な王朝と領土を回復すべきだという正統主義を唱えた。ナポレオンを生んだのは革命であり、ブルボン家のフランスはその被害者だという論理で、フランスの領土を守り、大国の一員として発言力を得た。',
        talk: '負けた国フランスの代表タレーランは、どうやって自分の国を守ったのでしょう。彼の切り札が「正統主義」でした。「ヨーロッパを荒らしたのは革命とナポレオンです。革命前の正しい王家、ブルボン家が戻ったフランスは、むしろ被害者なのです」。そして、革命前の王朝と国境に戻すことこそ正しい、と主張しました。タレーラン自身は、革命政府にもナポレオンにも仕えた人物です。その変わり身の早さには、驚くしかありませんね。',
        place: 'ウィーン', lon: 16.37, lat: 48.21, span: 1,
        polities: ['france', 'austria']
      },
      {
        year: 1815, title: 'ブルボン家の復活',
        text: '正統主義にもとづき、フランスではルイ18世、スペインと両シチリア王国でもブルボン家が復位した。一方で、ポーランドやザクセンの扱いでは大国の利害が優先され、ヴェネツィア共和国や神聖ローマ帝国は復活しなかった。',
        talk: '正統主義によって、フランス、スペイン、ナポリのブルボン家が王の座に戻りました。でも、この原則はいつも守られたわけではありません。たとえば、1000年以上続いたヴェネツィア共和国は復活せず、オーストリアのものになりました。ポーランドの大部分はロシア皇帝が王をかねる王国になります。結局、大国の勢力のつり合いをとる「勢力均衡」が優先されたのです。正統主義は、大国にとって都合のよいときに使われる理屈でもありました。',
        place: 'パリ', lon: 2.35, lat: 48.86, span: 20,
        polities: ['france-19', 'spain', 'two-sicilies', 'austria', 'russia', 'prussia']
      },
      {
        year: 1830, title: 'ゆらぐウィーン体制',
        text: 'ウィーン体制のもとでは、神聖同盟や四国同盟によって自由主義や民族主義の運動が抑えられた。しかし1830年のフランス七月革命でブルボン家の王が追放され、1848年の革命でメッテルニヒが失脚して、ウィーン体制は崩壊した。',
        talk: '正統主義のもとでつくられたウィーン体制は、王や皇帝の秩序を守るため、自由を求める声や、民族ごとに国をつくろうとする動きをきびしく押さえつけました。しかし、フランス革命で広まった考えを消すことはできません。1830年、フランスでは七月革命が起こり、正統なはずのブルボン家の王が追い出されます。そして1848年、ウィーンでも革命が起こり、メッテルニヒはイギリスへ亡命しました。正統主義の時代は終わりを告げたのです。',
        place: 'パリ', lon: 2.35, lat: 48.86, span: 15,
        polities: ['france-19', 'austria'], people: ['metternich']
      }
