        text: 'マルクス主義は、19世紀後半の労働運動や社会主義政党に大きな影響を与え、1917年のロシア革命の指導者レーニンもその理論を受け継いだ。宣言は多くの言語に翻訳され、日本では1904年に幸徳秋水・堺利彦が初めて訳した。',
        talk: '出版された当時はほとんど注目されなかったこの冊子は、その後、世界中で読まれるようになります。労働者の政党がつくられ、マルクスの考えはその旗じるしとなりました。そして1917年、ロシアで革命を起こしたレーニンは、マルクスの理論をもとに、世界初の社会主義国家をつくります。日本でも1904年、幸徳秋水と堺利彦が新聞に翻訳をのせましたが、すぐに発売禁止となりました。20世紀、世界の3分の1の人々が社会主義の国に住むことになります。',
