        talk: '1991年にソ連が解体し、多くの社会主義の国はなくなりました。では、『共産党宣言』はもう役目を終えたのでしょうか。実は今も、世界中で読まれ続けています。お金持ちと貧しい人の差が広がるなか、資本主義のしくみを考え直すための本として読まれているのです。2013年、ユネスコは、マルクスの手書きの草稿のページと『資本論』を「世界の記憶」に登録しました。賛成するにせよ反対するにせよ、人類が向き合ってきた大切な記録だというわけです。',
        place: 'アムステルダム（国際社会史研究所）', lon: 4.94, lat: 52.37, span: 10,
