        text: '南部の議員が去った議会で、1862年5月、ホームステッド法が成立した。21歳以上の市民（または市民権を申請した移民）は、公有地160エーカー（約65ヘクタール）を申請し、5年間住んで耕せば、わずかな手数料で自分のものにできた。女性や解放された奴隷も申請できた。',
