        talk: '福沢諭吉は、九州の中津藩の、身分の低い武士の家に生まれました。父は学問好きでしたが、家柄が低いため出世できないまま、若くして亡くなります。どんなに能力があっても、生まれた家で一生が決まってしまう。諭吉は自伝に「門閥制度は親のかたきでござる」と書いています。19歳で長崎へ、そして大坂の緒方洪庵の適塾でオランダ語の学問、蘭学を必死に学びました。この悔しさが、のちの『学問のすゝめ』の出発点になります。',
        place: '大坂（適塾）', lon: 135.5, lat: 34.69, span: 4,
        polities: ['japan-pre'], people: ['fukuzawa'],
