        talk: '1872年、明治5年に出た『学問のすゝめ』は、この有名な一文で始まります。「天は人の上に人を造らず人の下に人を造らずと云えり」。最後の「と云えり」に注意してください。「と言われている」という意味で、アメリカ独立宣言などの考えを紹介したものだと考えられています。そして諭吉は続けます。それなのに、世の中には賢い人も愚かな人も、金持ちも貧しい人もいる。その差はどこから来るのか。答えは「学ぶか、学ばないか」だ、と。',
