        talk: '『学問のすゝめ』は、1876年までに17冊のシリーズとして出版されました。売れた部数は合わせて300万部以上ともいわれます。当時の日本の人口は約3500万人ですから、驚くべき数です。にせものの印刷版も出回るほどでした。諭吉はこう訴えます。「一身独立して一国独立す」。一人ひとりが自分の頭で考え、自分の力で生きていけるようになってこそ、日本という国も、欧米の強国に負けずに独立を守れる。学問は、自分のためであり、国のためでもあったのです。',
