        talk: '福沢諭吉の開いた塾は、1868年に慶應義塾と名づけられ、今も大学として続いています。1984年からは一万円札の顔となり、40年間、日本でいちばん高いお札にその姿がありました。一方で、晩年の諭吉は、日本はアジアの国々と縁を切って欧米の側に立つべきだという考えも示しており、その主張には今も批判があります。偉人の言葉は、その時代の中で読むことが大切です。あなたは、『学問のすゝめ』のどの言葉に共感しますか。',
