        talk: 'なぜ19世紀の終わりに、ヨーロッパの国々は競って植民地を広げたのでしょうか。1873年、ヨーロッパは長い不況におちいりました。同じころ、電気や化学、鉄鋼などの新しい産業が育ち、巨大な企業や銀行が生まれます。国の中だけでは、もうけを生む場所が足りない。原料も安く手に入れたい。そこで各国は、海外に目を向けました。工場の製品を売る市場、お金を投資する先、そして原料のとれる土地を、自分の国のものにしようとしたのです。',
