        talk: '問題を話し合うため、1906年、ジブラルタル海峡に面したスペインの町アルヘシラスで国際会議が開かれました。ドイツの予想に反して、イギリスはしっかりとフランスの味方につきます。アメリカやロシア、さらにドイツと同盟を結んでいたイタリアまでもが、フランス寄りの態度をとりました。ドイツを支持したのは、オーストリアだけ。英仏の仲を割くどころか、ドイツの孤立をはっきり見せる結果になったのです。',
