        talk: '1869年にスエズ運河を完成させたフランスのレセップスは、英雄でした。「次はパナマだ」。1881年、レセップスの会社はパナマで工事を始めます。ところが、平らな砂漠のスエズとちがい、パナマには山と密林と、雨季になるとあふれる川がありました。海の高さのまま山を切り開く計画は、無理があったのです。さらに、蚊が運ぶ黄熱病やマラリアで、2万人以上の労働者が命を落としたといわれます。1889年、会社は破産しました。',
