        text: '1898年の米西戦争の際、アメリカの戦艦オレゴンはサンフランシスコから南アメリカ南端を回ってキューバ方面に向かい、約2か月を要した。両大洋を結ぶ運河の軍事的な必要性がアメリカで強く意識された。',
        talk: '1898年、アメリカはスペインと戦争を始めます。戦場はカリブ海のキューバ。そこで太平洋岸のサンフランシスコにいた戦艦オレゴンに、出動命令が出ました。ところが、南北アメリカ大陸がじゃまをして、まっすぐ行けません。オレゴンは南アメリカの南の端をぐるりと回り、2万キロ以上、2か月あまりかけて、ようやくカリブ海にたどり着きました。「パナマに運河があれば」。アメリカ中の人がそう思った事件でした。',
