        talk: 'アメリカがまず取り組んだのは、工事よりも蚊との戦いでした。軍医ゴーガスは、水たまりをなくし、家に網戸をつけて、黄熱病をほぼなくすことに成功します。そして、山を全部けずるのではなく、川をせき止めて山の上に大きな湖をつくり、船を水門で階段のように持ち上げて越えさせる方法を選びました。船は約26メートル上の湖へ上り、また下りて反対側の海に出ます。1914年8月15日、ついに運河は開通しました。',
