        talk: '1917年のロシアは、戦争に疲れきっていました。何百万人もの兵士が死んだり傷ついたりし、町ではパンを買う行列が長くのびています。2月、ついに民衆が立ち上がり、皇帝ニコライ2世は退位しました。ところが、新しくできた臨時政府は、連合国との約束を守って戦争を続けようとします。「パンと平和と土地を」。人々が求めたのは、とにかく戦争を終わらせることでした。スイスから帰国したレーニンは、その声をつかみます。',
        place: 'ペトログラード', lon: 30.32, lat: 59.94, span: 8,
        polities: ['russia'], people: ['lenin', 'nicholas-2']
