        talk: '1917年11月7日、ボリシェヴィキは首都ペトログラードで武装蜂起し、冬宮にいた臨時政府を倒しました。ロシアの古い暦では10月だったので、十月革命と呼びます。そして翌日、労働者や兵士の代表が集まるソヴィエトの大会で、レーニンは2つの布告を読み上げました。一つは地主の土地を取り上げて農民に分ける「土地に関する布告」。そしてもう一つが、戦争をやめようと世界に呼びかける「平和に関する布告」でした。',
        place: 'スモーリヌイ（ペトログラード）', lon: 30.4, lat: 59.95, span: 0.4,
