        text: '布告は、すべての交戦国の政府と国民に、無併合・無賠償・民族自決にもとづく即時の講和を呼びかけた。また秘密外交の廃止を宣言し、ソヴィエト政府は帝政ロシアが連合国と結んだ秘密条約を公表した。',
        talk: '布告の中身は、とても大胆なものでした。他国の領土を取らない（無併合）。お金を取らない（無賠償）。それぞれの民族が自分たちの運命を決める（民族自決）。この条件で、今すぐ戦争をやめよう、と世界に呼びかけたのです。さらにソヴィエト政府は、帝政ロシアが連合国とこっそり結んでいた秘密条約を、次々と新聞で公表しました。オスマン帝国の領土をイギリス・フランス・ロシアで分ける約束などが明らかになり、世界は驚きました。',
        place: 'ペトログラード', lon: 30.32, lat: 59.94, span: 30,
        polities: ['soviet-russia', 'germany', 'britain', 'france-19', 'austria-hungary', 'ottoman']
