        talk: 'レーニンの呼びかけは、戦争に疲れた世界中の人々の心をつかむおそれがありました。これに対抗したのが、アメリカのウィルソン大統領です。1918年1月、ウィルソンは「十四か条の平和原則」を発表しました。秘密外交をやめること、海を自由に行き来できること、そして民族自決。レーニンの布告とよく似た内容もふくまれています。社会主義の革命政府と、民主主義の大国アメリカ。二つの呼びかけが、戦後の世界をめぐって競い合ったのです。',
