        talk: '残念ながら、イギリスやフランスはレーニンの呼びかけに応じませんでした。そこでソヴィエト政府は、ドイツと単独で講和の交渉を始めます。交渉を担当したトロツキーは引きのばしをはかりますが、ドイツ軍が再び進撃してきたため、1918年3月、ブレスト=リトフスクで条約を結ぶしかありませんでした。ロシアは、ポーランドやバルト地方、ウクライナなど、広大な領土を手放します。「無併合」を訴えた政府が、大きな併合を受け入れることになったのです。',
