        text: '1919年8月に制定された憲法は、主権在民を定め、20歳以上の男女に選挙権を与えた。第151条は「人間に値する生存」の保障を経済生活の目的とし、労働者の団結権なども認めて、社会権を初めて本格的に定めた憲法とされる。',
        talk: '1919年8月、ヴァイマル憲法が定められました。20歳以上のすべての男女に選挙権。そして注目すべきは、第151条です。経済の目的は、すべての人に「人間に値する生存」を保障することにある、と書かれています。それまでの憲法は、国が個人の自由をじゃましないことを主に定めていました。この憲法は一歩進んで、国が人々の暮らしを支える責任を定めたのです。日本国憲法25条の生存権も、こうした考えの流れをくんでいます。',
