        year: 1918, title: '戦時共産主義',
        text: '革命後のロシアでは、反革命軍との内戦と外国の干渉戦争が起こった。ソヴィエト政府は戦時共産主義をとり、企業を国有化し、私的な商業を禁止して、農民から穀物を強制的に徴発した。',
        talk: '革命の後、ロシアはすぐに平和になったわけではありません。旧帝政派の白軍との内戦が起こり、イギリスや日本などの外国も軍を送ってきました。ソヴィエト政府は生きのびるため、「戦時共産主義」と呼ばれる政策をとります。工場はすべて国のものにし、自由な売り買いは禁止。そして、農民の家に兵士を送り、余った穀物を強制的に取り上げて、兵士や都市の労働者に配りました。戦うためには仕方ない、という理屈でした。',
