        talk: 'ネップの効果は目に見えて表れました。1921年から翌年にかけてヴォルガ地方では大ききんが起き、多くの人が亡くなりましたが、その後、農業も工業も少しずつ回復し、1926年ごろには戦争前の水準にほぼもどります。1922年にはソ連が成立しました。しかし1924年、レーニンが亡くなると、党の中で後継者争いが始まります。ネップを続けるべきか、急いで工業化を進めるべきか。この争いに勝ったのがスターリンでした。',
