        text: '広い植民地をもつイギリス・フランス・アメリカに対し、日本・ドイツ・イタリアは自らを「持たざる国」と主張した。日本は満洲を含む円ブロック、ドイツは中南欧を経済圏に組みこもうとし、領土の拡大をはかった。',
