        talk: '第二次世界大戦の終わりが見えてきた1944年、連合国の代表がアメリカのブレトン=ウッズに集まりました。二度と同じ過ちをくり返さないためです。通貨を安定させるための国際通貨基金がつくられ、1947年には、関税を下げて自由に貿易するためのGATTという協定が結ばれました。これが今の世界貿易機関、WTOにつながります。今もニュースで「関税の引き上げ」が話題になることがありますね。1930年代の教訓を思い出すべき場面かもしれません。',
