        talk: '1956年、ソ連の指導者フルシチョフは、秘密の会議で衝撃的な演説をしました。亡くなったスターリンが、多くの無実の人を処刑し、自分を神のように崇めさせていた、と批判したのです。さらにフルシチョフは、アメリカなど資本主義の国とも戦争をせず、平和に共存できると言いました。これに毛沢東は反発します。自分も個人崇拝されている毛沢東にとって、スターリン批判は人ごとではありません。「ソ連は革命の道からはずれた」。論争が始まりました。',
