        talk: '1960年夏、中国の工場や建設現場から、ソ連の技術者たちが一斉にいなくなりました。その数、約1400人。設計図まで持ち帰ってしまい、つくりかけの工場はそのまま放っておかれました。その前年には、原爆の技術を教えるという約束も取り消されています。ちょうど中国は、毛沢東の大躍進政策の失敗で多くの人が飢えに苦しんでいるときでした。それでも中国は、1964年、自分たちの力で原爆の実験に成功します。',
