        talk: '1969年3月、凍りついたウスリー川の上で、銃声がひびきました。中国とソ連の国境の川に浮かぶ小さな島、中国では珍宝島、ソ連ではダマンスキー島と呼ぶ場所で、両国の軍隊がぶつかったのです。戦車や大砲も使われ、多くの兵士が亡くなりました。夏には西の新疆でも衝突が起こります。かつての同盟国どうしが、核兵器を使った戦争をするのではないか。世界中が息をのみました。社会主義の兄弟げんかは、本物の戦いになったのです。',
