    period: '1968年', region: 'europe', view: 'centraleurope', tags: ['sogo'],
    summary: '1968年、チェコスロヴァキアでドプチェクが進めた民主化・自由化の運動。検閲を廃止し「人間の顔をした社会主義」をめざしたが、ソ連などワルシャワ条約機構5か国の軍事介入で押しつぶされた。21年後のビロード革命で、その願いは実を結んだ。',
