        talk: 'ドプチェクがめざしたのは、「人間の顔をした社会主義」でした。社会主義はやめない。でも、人々が自由にものを言い、考えられる社会にしたい。4月に発表された行動綱領では、言論や集会の自由が約束され、まもなく検閲もなくなりました。新聞やテレビは、それまで言えなかった政府への批判や、過去の弾圧について語り始めます。カフェでは人々が夜遅くまで議論しました。長い冬のあとにやってきた春のような日々でした。',
