        talk: 'ヨーロッパの国々は、20世紀前半に二度も大きな戦争をしました。もう二度と戦わないためにどうするか。答えの一つが、経済をひとつに結びつけることでした。1952年、戦争に欠かせない石炭と鉄鋼を、フランスや西ドイツなど6か国で共同管理することから統合は始まります。やがて関税をなくした共同市場ができ、1979年には、加盟国のお金の交換の比率を安定させるしくみもつくられました。共通のお金への第一歩です。',
