        talk: '1990年、ドイツが統一されると、周りの国々には不安もありました。大きくなったドイツを、ヨーロッパの中にしっかりつなぎとめておきたい。1992年、オランダの町マーストリヒトで結ばれた条約で、ヨーロッパ連合、EUが生まれ、共通のお金をつくることが決まりました。ただし、参加するには条件があります。国の借金や赤字を一定の範囲におさえることです。お金を共通にする以上、ほかの国に迷惑をかけないようにしよう、というわけです。',
