        talk: '1999年1月1日、ドイツ、フランス、イタリアなど11か国で、新しいお金「ユーロ」が誕生しました。ただし、最初は目に見えるお札や硬貨はありません。銀行どうしのお金のやりとりや、株の取引などに使われる、帳簿の上のお金でした。お金の量や金利を決めるのは、ドイツのフランクフルトに置かれた欧州中央銀行です。それぞれの国は、自分の国のお金を自由に動かす権利を、みんなでつくった銀行にあずけたのです。',
