        talk: '2002年1月1日の朝、ヨーロッパの人々の財布に、初めてユーロのお札と硬貨が入りました。ドイツのマルク、フランスのフランなど、長い歴史のあるお金が消えていきます。ユーロのお札には、窓や門、橋が描かれていますが、実はどれも実在しない、想像上の建物です。どこか一つの国の建物を選ぶと、ほかの国が不公平だと感じるからです。一方、硬貨の裏側は国ごとにデザインがちがいます。共通と個性を両立させる工夫ですね。',
